// src/utils/terminalTitle.ts
function setTerminalTitle(title) {
  const clean = title.replace(/[\x00-\x1f\x7f]/g, "").trim();
  if (!clean) return;
  if (process.platform === "win32") {
    process.title = clean;
    return;
  }
  process.stdout.write(`\x1B]0;${clean}\x07`);
}

